BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout='30s';
SET LOCAL timezone='UTC';
SELECT jsonb_build_object('kind','window','capturedAt',now(),'webActivatedAt',:'activated_at'::timestamptz,'workerStartedAt',:'worker_started_at'::timestamptz,'secondsSinceWebActivation',extract(epoch FROM now()-:'activated_at'::timestamptz),'expectedVersion',:'release_sha','nextTenMinuteBucket',to_timestamp((floor(extract(epoch FROM now())/600)+1)*600));
SELECT jsonb_build_object('kind','content','active',(SELECT jsonb_agg(jsonb_build_object('id',id,'version',version,'activatedAt',activated_at)) FROM content_revisions WHERE status='active'),'counts',(SELECT jsonb_agg(x ORDER BY mode) FROM(SELECT mode,count(*) total,count(*) FILTER(WHERE allowed_in_game) allowed FROM content_item_versions WHERE revision_id=(SELECT id FROM content_revisions WHERE status='active') GROUP BY mode)x),'revisionsCreatedAfterWorkerStart',(SELECT count(*) FROM content_revisions WHERE "createdAt">=:'worker_started_at'::timestamptz));
WITH recent AS(SELECT status,"createdAt",started_at,finished_at,attempts,created_by IS NOT NULL manually_created,idempotency_key LIKE 'scheduled:commerce-reconcile:%' scheduled,error_code,
 (SELECT count(*) FROM jsonb_array_elements(CASE WHEN jsonb_typeof(result->'reconciled')='array' THEN result->'reconciled' ELSE '[]'::jsonb END) e WHERE e->>'status'='pending') reconciled_pending,
 (SELECT count(*) FROM jsonb_array_elements(CASE WHEN jsonb_typeof(result->'reconciled')='array' THEN result->'reconciled' ELSE '[]'::jsonb END) e WHERE e->>'status'='paid') reconciled_paid
 FROM background_jobs WHERE type='commerce_reconcile' AND ("createdAt">=:'worker_started_at'::timestamptz OR finished_at>=:'worker_started_at'::timestamptz) ORDER BY "createdAt" DESC LIMIT 10)
SELECT jsonb_build_object('kind','commerceJobs','rows',coalesce((SELECT jsonb_agg(recent ORDER BY "createdAt") FROM recent),'[]'::jsonb),'newScheduledCompleted',(SELECT count(*) FROM background_jobs WHERE type='commerce_reconcile' AND idempotency_key LIKE 'scheduled:commerce-reconcile:%' AND created_by IS NULL AND "createdAt">=:'worker_started_at'::timestamptz AND status='completed'),'newScheduledFailed',(SELECT count(*) FROM background_jobs WHERE type='commerce_reconcile' AND idempotency_key LIKE 'scheduled:commerce-reconcile:%' AND "createdAt">=:'worker_started_at'::timestamptz AND status='failed'),'newManuallyCreated',(SELECT count(*) FROM background_jobs WHERE type='commerce_reconcile' AND created_by IS NOT NULL AND "createdAt">=:'worker_started_at'::timestamptz));
WITH x AS(SELECT status,provider_status,count(*) orders,count(*) FILTER(WHERE p.role='admin') staff_orders,count(*) FILTER(WHERE paid_at IS NOT NULL) paid,
 count(*) FILTER(WHERE metadata->>'lastReconciliationOutcome'='awaiting_payment') awaiting_payment,
 count(*) FILTER(WHERE metadata->>'lastReconciliationError' LIKE 'ORDER_NOT_FOUND:%') old_or_current_not_found_metadata,
 count(*) FILTER(WHERE metadata->>'lastReconciliationError' LIKE 'ORDER_NOT_FOUND:%' AND nullif(metadata->>'lastReconciliationFailedAt','')::timestamptz>=:'worker_started_at'::timestamptz) not_found_after_worker_start,
 max(metadata->>'lastReconciledAt') latest_check,max(metadata->>'lastReconciliationFailedAt') latest_failure,
 count(*) FILTER(WHERE EXISTS(SELECT 1 FROM user_entitlements e WHERE e.source_type='order' AND e.source_id=o.id::text)) orders_with_entitlements
 FROM payment_orders o LEFT JOIN player_profiles p ON p.user_id=o.user_id WHERE o.status IN('created','pending') OR o."createdAt">=:'worker_started_at'::timestamptz GROUP BY status,provider_status)
SELECT jsonb_build_object('kind','paymentState','rows',coalesce((SELECT jsonb_agg(x) FROM x),'[]'::jsonb));
WITH e AS(SELECT event_name,CASE WHEN app_version ~ '^[a-f0-9]{40}$' THEN app_version WHEN app_version IN('dev','unknown') THEN app_version ELSE '(unknown/legacy)' END version,CASE WHEN p.role='admin' THEN 'admin' ELSE 'non_admin' END cohort,e.user_id,e.occurred_at,e."createdAt",error_code,
 CASE WHEN properties->>'message' ~* 'JSON|Unexpected token|Unterminated string' THEN 'invalid_json'
 WHEN properties->>'message' ~* 'view.transition|transition was (skipped|aborted)' THEN 'view_transition'
 ELSE 'other' END error_class
 FROM client_events e LEFT JOIN player_profiles p ON p.user_id=e.user_id WHERE occurred_at>=:'activated_at'::timestamptz AND occurred_at<=now() AND e."createdAt">=:'activated_at'::timestamptz),
 counts AS(SELECT version,cohort,event_name,count(*) events,count(distinct user_id) profiles,count(*) FILTER(WHERE user_id IS NULL) unlinked_events FROM e GROUP BY 1,2,3),
 errors AS(SELECT version,cohort,event_name,CASE WHEN error_code ~ '^[A-Za-z0-9_:-]{1,100}$' THEN error_code ELSE '(unspecified)' END error_code,error_class,count(*) events,count(distinct user_id) profiles FROM e WHERE event_name IN('client_error','api_error','report_submit_failed') GROUP BY 1,2,3,4,5)
SELECT jsonb_build_object('kind','clientEventsByVersion','counts',coalesce((SELECT jsonb_agg(counts ORDER BY version,cohort,event_name) FROM counts),'[]'::jsonb),'errors',coalesce((SELECT jsonb_agg(errors ORDER BY version,cohort,event_name,error_code) FROM errors),'[]'::jsonb),'limitation','Only events observed in this short window; versions from stale tabs remain separate, absence of reports is not proof of no errors.');
WITH x AS(SELECT type,status,CASE WHEN error_code ~ '^[A-Za-z0-9_:-]{1,100}$' THEN error_code ELSE NULL END error_code,count(*) jobs FROM background_jobs WHERE type IN('danetki_guess_evaluate','danetki_ai_reply') AND "createdAt">=:'worker_started_at'::timestamptz GROUP BY 1,2,3),
 a AS(SELECT action,entity_type,result,count(*) entries FROM audit_log WHERE "createdAt">=:'worker_started_at'::timestamptz AND action ~* 'retry|replay|requeue|reconcil|payment|commerce|content.*(activ|import)|setting' GROUP BY 1,2,3)
SELECT jsonb_build_object('kind','operationalScope','danetkiJobs',coalesce((SELECT jsonb_agg(x) FROM x),'[]'::jsonb),'relevantAdminAuditActions',coalesce((SELECT jsonb_agg(a) FROM a),'[]'::jsonb),'limitation','Collector performs no writes or job replays. Audit-log absence alone cannot prove absence of every possible SQL mutation by another actor.');
ROLLBACK;
